        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Follow-up is a journey, not a chase',
      lesson_number = 1,
      sort_order = 1,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Follow-up is a journey, not a chase';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Follow-up is a journey, not a chase

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 17 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 17 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'follow-up-is-journey' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson follow-up-is-journey not found in module 17';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three things a lead wants to know after submitting an enquiry?', 
    '["Price, features, and competitors","Did you receive my message? Can you help me? What should I do next?","How fast, how cheap, how good","Who are you, what do you do, why should I care"]'::jsonb,
    'Did you receive my message? Can you help me? What should I do next?',
    'A lead wants to know: Did you receive my message? Can you help me? What should I do next? A useful response answers these three questions without overwhelming them.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the correct order of the five-step follow-up formula?', 
    '["Invite, Capture, Respond, Check, Follow up","Capture, Respond, Invite, Check, Follow up","Capture, Check, Respond, Invite, Follow up","Respond, Capture, Invite, Follow up, Check"]'::jsonb,
    'Capture, Respond, Invite, Check, Follow up',
    'The five-step formula is: 1. Capture (form submission), 2. Respond (acknowledgement), 3. Invite (clear next step), 4. Check (allow time), 5. Follow up (single reminder if needed).', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many follow-up reminders should you send if there is no response?', 
    '["As many as it takes until they reply","Three reminders over two weeks","A single relevant reminder","None — never follow up"]'::jsonb,
    'A single relevant reminder',
    'The formula recommends sending a single relevant reminder if there has been no response or booking. Multiple unsolicited follow-ups can feel like chasing and damage trust.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
